"""Field-client auth for ПСС /api/* routes.

Flask-Security @auth_required expects a session or Basic password. Field
apps enroll with a client certificate and often have no OTS account
password stored — mTLS on :8443 already proves identity via nginx
X-Ssl-Cert. This helper logs the user in from the cert CN (or Basic
password / enrollment JWT) so @auth_required passes.
"""

from __future__ import annotations

import base64
import json
import os
import traceback

import jwt
from flask import request
from flask_security import current_user, login_user, verify_password

from opentakserver.blueprints.marti_api.marti_api import verify_client_cert
from opentakserver.extensions import db, logger
from opentakserver.models.Token import Token


def try_login_field_client() -> bool:
    """Authenticate current request if not already logged in. Returns True if authenticated."""
    try:
        if current_user is not None and getattr(current_user, "is_authenticated", False):
            return True
    except Exception:
        pass

    user = _user_from_basic() or _user_from_client_cert()
    if not user:
        return False
    try:
        login_user(user)
        return True
    except Exception as e:
        logger.warning("psr field login_user failed: %s", e)
        return False


def _find_user(username: str):
    if not username:
        return None
    try:
        from flask import current_app as app

        return app.security.datastore.find_user(username=username)
    except Exception:
        return None


def _user_from_basic():
    auth = request.headers.get("Authorization") or ""
    if not auth.lower().startswith("basic "):
        return None
    try:
        raw = base64.b64decode(auth.split(" ", 1)[1].encode("utf-8")).decode("utf-8")
        username, password = raw.split(":", 1)
    except Exception:
        return None
    username = (username or "").strip()
    password = password or ""
    if not username or not password:
        return None
    user = _find_user(username)
    if not user:
        return None
    try:
        if verify_password(password, user.password):
            return user
    except Exception:
        pass
    # Enrollment JWT as password (do not burn token uses — identity only).
    if _token_valid_for_user(password, username):
        return user
    return None


def _token_valid_for_user(token: str, username: str) -> bool:
    """Validate enrollment JWT without incrementing Token.total_uses."""
    try:
        from flask import current_app as app

        pub_path = os.path.join(
            app.config.get("OTS_CA_FOLDER"),
            "certs",
            "opentakserver",
            "opentakserver.pub",
        )
        with open(pub_path, "r") as key:
            decoded = jwt.decode(
                token, key.read(), algorithms=["RS256"], audience="OpenTAKServer"
            )
        if decoded.get("sub") != username:
            return False
        sha256 = __import__("hashlib").sha256()
        sha256.update(json.dumps(decoded).encode())
        token_hash = sha256.hexdigest()
        row = db.session.query(Token).filter_by(token_hash=token_hash).first()
        if not row or row.disabled:
            return False
        if row.username and row.username != username:
            return False
        return True
    except Exception as e:
        logger.debug("psr token check failed: %s", e)
        return False


def _user_from_client_cert():
    try:
        cert = verify_client_cert()
    except Exception as e:
        logger.debug("psr verify_client_cert error: %s\n%s", e, traceback.format_exc())
        return None
    if not cert:
        return None
    try:
        cn = cert.get_subject().CN
    except Exception:
        cn = None
    if not cn:
        return None
    user = _find_user(cn)
    if not user:
        logger.warning("psr mTLS CN=%s has no OTS user", cn)
    return user


def register_field_auth(blueprint) -> None:
    """before_request: promote mTLS / Basic / JWT into a Flask-Security session."""

    @blueprint.before_request
    def _psr_field_auth():
        # Only field SAR routes need this; skip OPTIONS.
        if request.method == "OPTIONS":
            return None
        path = request.path or ""
        if not (
            path.startswith("/api/missions/")
            or path.startswith("/api/search_sectors")
            or path.startswith("/api/tracks")
        ):
            return None
        try_login_field_client()
        return None
